import json, re
d = json.load(open('/tmp/bd_mems_live.json'))
# how many are 'iteration recipts': mention 'iter N' or 'commit XXXX' or specific dates plus 'closed/landed/merged'
# Distinguish potential cleanup targets from durable rules
buckets = {'closed_status': [], 'iter_log': [], 'invariant_prefix': [], 'avoid_prefix': [], 'has_commit_hash': [], 'short_durable': []}
for k, v in d.items():
    if re.search(r'\b(landed|merged|reverted in commit|superseded by|fixed in commit|completed|closed)\b', v, re.I):
        buckets['closed_status'].append(k)
    if re.search(r'\biter\s*\d+\b', v, re.I):
        buckets['iter_log'].append(k)
    if k.startswith('invariant-'):
        buckets['invariant_prefix'].append(k)
    if k.startswith('avoid-'):
        buckets['avoid_prefix'].append(k)
    if re.search(r'\bcommit\s+[0-9a-f]{7,}\b', v):
        buckets['has_commit_hash'].append(k)
    if len(v) < 400 and not re.search(r'\b(landed|closed|merged)\b', v, re.I):
        buckets['short_durable'].append(k)
for b, ks in buckets.items():
    print(f'{b}: {len(ks)}')
"

